import React, { useEffect, useState } from "react";

// Tries a same-name .webp sibling first (generated by scripts/optimize_png.py
// for everything under public/pousadas and public/species at the time it
// last ran), and silently falls back to the original src via onError if that
// .webp 404s — which covers admin-uploaded photos added after the script ran
// and never got a sibling. <picture><source> can't do this: once the browser
// picks a source it doesn't retry on a failed fetch, so a missing .webp would
// render as a broken image instead of falling back.
type Props = React.ImgHTMLAttributes<HTMLImageElement> & { src: string };

// Exported standalone so it's unit-testable without rendering the component.
export function toWebpCandidate(src: string): string | null {
  const isLocalRaster = /^\/(pousadas|species)\/.+\.(png|jpe?g)$/i.test(src);
  return isLocalRaster ? src.replace(/\.(png|jpe?g)$/i, ".webp") : null;
}

// Foto que não carrega de jeito nenhum (link externo removido, por exemplo)
// vira um fundo neutro com ícone, em vez do ícone de "imagem quebrada" e do
// texto alternativo vazando por cima do card.
const BROKEN_PLACEHOLDER =
  "data:image/svg+xml;charset=utf-8," +
  encodeURIComponent(
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 260" preserveAspectRatio="xMidYMid slice"><rect width="400" height="260" fill="#E9E4D8"/><g fill="none" stroke="#A39C8C" stroke-width="6" stroke-linejoin="round" transform="translate(170 100)"><rect x="0" y="0" width="60" height="44" rx="4"/><path d="M6 38l16-16 12 12 8-8 12 12"/><circle cx="44" cy="12" r="5"/></g></svg>'
  );

export default function PictureImg({ src, onError, ...imgProps }: Props) {
  const webpSrc = toWebpCandidate(src);
  const [failed, setFailed] = useState(false);
  const [broken, setBroken] = useState(false);
  // Galerias trocam o src no mesmo componente: cada foto nova tenta de novo.
  useEffect(() => {
    setFailed(false);
    setBroken(false);
  }, [src]);

  return (
    <img
      loading="lazy"
      decoding="async"
      {...imgProps}
      src={broken ? BROKEN_PLACEHOLDER : webpSrc && !failed ? webpSrc : src}
      alt={broken ? "" : imgProps.alt}
      onError={e => {
        if (webpSrc && !failed) setFailed(true);
        else if (!broken) setBroken(true);
        onError?.(e);
      }}
    />
  );
}
